contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint v1, uint v2) public payable {
        require(v1 != v2);

        c.SetMinSum(v1); if (__ESBMC_reverted()) return;
        c.SetMinSum(v2); if (__ESBMC_reverted()) return;

        uint stored = c.MinSum(); if (__ESBMC_reverted()) return;

        assert(stored == v2);
    }

    receive() external payable {}
}

